/**
 * Tests for the hand-rolled SigV4 conditional writer.
 *
 * A signer is either byte-exact or useless, and "it worked against the bucket
 * once" is not a test. The signature cases below are REFERENCE VECTORS
 * generated by botocore's `S3SigV4Auth` (the signer boto3/awscli use) for the
 * identical request, so this suite pins our output against an independent
 * implementation rather than against itself. Regenerate with:
 *
 *   python3 scripts/metal-agent/gen-sigv4-vectors.py
 *
 * The timestamp is part of each vector because SigV4 binds the signature to
 * the request time; the signer takes `now` as an argument for exactly this.
 */

import { describe, expect, test } from 'bun:test'

import {
  amzDates,
  canonicalUriFor,
  conditionalPutObject,
  objectUrl,
  signPutHeaders,
  type S3Target,
} from './s3-conditional'

const TARGET: S3Target = {
  endpoint: 'https://mynamespace.compat.objectstorage.us-ashburn-1.oraclecloud.com',
  region: 'us-ashburn-1',
  bucket: 'shogo-workspaces-production',
  accessKeyId: 'AKIAIOSFODNN7EXAMPLE',
  secretAccessKey: 'wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY',
}

/** Generated by botocore — see the file header. */
const VECTORS = [
  {
    name: 'if-match compare-and-swap',
    key: 'proj-abc/project-data.tar.gz',
    body: new TextEncoder().encode('gzip-bytes-here'),
    contentType: 'application/gzip',
    precondition: { ifMatch: '"d41d8cd98f00b204e9800998ecf8427e"' },
    amzDate: '20260807T040659Z',
    authorization:
      'AWS4-HMAC-SHA256 Credential=AKIAIOSFODNN7EXAMPLE/20260807/us-ashburn-1/s3/aws4_request, ' +
      'SignedHeaders=content-length;content-type;host;if-match;x-amz-content-sha256;x-amz-date, ' +
      'Signature=a5163ca5627e935273b4fb00aa2bd574de35477b78b03af16ae0199146411705',
  },
  {
    name: 'if-none-match create-only',
    key: 'proj-abc/project-data.tar.gz',
    body: new Uint8Array(0),
    contentType: 'application/gzip',
    precondition: { ifNoneMatch: '*' as const },
    amzDate: '20260807T040659Z',
    authorization:
      'AWS4-HMAC-SHA256 Credential=AKIAIOSFODNN7EXAMPLE/20260807/us-ashburn-1/s3/aws4_request, ' +
      'SignedHeaders=content-length;content-type;host;if-none-match;x-amz-content-sha256;x-amz-date, ' +
      'Signature=78d638e01fad9fc65bd4ce528f1e61c54cf421c8d145da1f08e4bfd62eac3890',
  },
  {
    name: 'key needing percent-encoding',
    key: 'proj abc/weird+name (1)/data.tar.gz',
    body: new Uint8Array([0, 1, 2, 98, 105, 110, 97, 114, 121]),
    contentType: 'application/octet-stream',
    precondition: undefined,
    amzDate: '20260807T040659Z',
    authorization:
      'AWS4-HMAC-SHA256 Credential=AKIAIOSFODNN7EXAMPLE/20260807/us-ashburn-1/s3/aws4_request, ' +
      'SignedHeaders=content-length;content-type;host;x-amz-content-sha256;x-amz-date, ' +
      'Signature=1429e988400c5704a81fcb0a5879973ca4b70a89fd19309086ce0b45d9b1c907',
  },
]

/** Turn a vector's `amzDate` back into the Date the signer should be given. */
function dateOf(amzDate: string): Date {
  const iso =
    `${amzDate.slice(0, 4)}-${amzDate.slice(4, 6)}-${amzDate.slice(6, 8)}T` +
    `${amzDate.slice(9, 11)}:${amzDate.slice(11, 13)}:${amzDate.slice(13, 15)}Z`
  return new Date(iso)
}

describe('signPutHeaders', () => {
  for (const v of VECTORS) {
    test(`matches botocore: ${v.name}`, () => {
      const headers = signPutHeaders({
        target: TARGET,
        key: v.key,
        payload: v.body,
        contentType: v.contentType,
        precondition: v.precondition,
        now: dateOf(v.amzDate),
      })
      expect(headers.authorization).toBe(v.authorization)
      expect(headers['x-amz-date']).toBe(v.amzDate)
    })
  }

  test('binds the precondition into the signature, not just the wire', () => {
    // If `if-match` were sent but left out of SignedHeaders, a proxy could strip
    // it and the write would silently become unconditional.
    const signed = signPutHeaders({
      target: TARGET,
      key: 'p/data.tar.gz',
      payload: new Uint8Array([1]),
      contentType: 'application/gzip',
      precondition: { ifMatch: '"abc"' },
      now: new Date('2026-08-07T04:06:59Z'),
    })
    expect(signed['if-match']).toBe('"abc"')
    expect(signed.authorization).toContain('if-match')

    // And a different precondition must produce a different signature.
    const other = signPutHeaders({
      target: TARGET,
      key: 'p/data.tar.gz',
      payload: new Uint8Array([1]),
      contentType: 'application/gzip',
      precondition: { ifMatch: '"xyz"' },
      now: new Date('2026-08-07T04:06:59Z'),
    })
    expect(other.authorization).not.toBe(signed.authorization)
  })

  test('signs the payload, so altered bytes invalidate the signature', () => {
    const base = {
      target: TARGET,
      key: 'p/data.tar.gz',
      contentType: 'application/gzip',
      now: new Date('2026-08-07T04:06:59Z'),
    }
    const a = signPutHeaders({ ...base, payload: new TextEncoder().encode('one') })
    const b = signPutHeaders({ ...base, payload: new TextEncoder().encode('two') })
    expect(a['x-amz-content-sha256']).not.toBe(b['x-amz-content-sha256'])
    expect(a.authorization).not.toBe(b.authorization)
  })
})

describe('addressing', () => {
  test('uses path-style with the bucket in the path', () => {
    expect(canonicalUriFor('bkt', 'a/b.tar.gz')).toBe('/bkt/a/b.tar.gz')
    expect(objectUrl(TARGET, 'p/data.tar.gz')).toBe(
      `${TARGET.endpoint}/${TARGET.bucket}/p/data.tar.gz`,
    )
  })

  test('encodes each segment but keeps separators literal', () => {
    expect(canonicalUriFor('bkt', 'a b/c(1)/d.gz')).toBe('/bkt/a%20b/c%281%29/d.gz')
  })

  test('tolerates a trailing slash on the endpoint', () => {
    expect(objectUrl({ ...TARGET, endpoint: `${TARGET.endpoint}/` }, 'k')).toBe(
      `${TARGET.endpoint}/${TARGET.bucket}/k`,
    )
  })

  test('formats both SigV4 date forms', () => {
    expect(amzDates(new Date('2026-08-07T04:06:59.123Z'))).toEqual({
      amzDate: '20260807T040659Z',
      dateStamp: '20260807',
    })
  })
})

describe('conditionalPutObject', () => {
  const put = (
    response: Response,
    precondition?: { ifMatch?: string; ifNoneMatch?: '*' },
  ): Promise<{ result: unknown; sent: Request | null }> => {
    let sent: Request | null = null
    const fetchImpl = (async (url: string, init: RequestInit) => {
      sent = new Request(url, init)
      return response
    }) as unknown as typeof fetch
    return conditionalPutObject({
      target: TARGET,
      key: 'p/data.tar.gz',
      body: new TextEncoder().encode('payload'),
      contentType: 'application/gzip',
      precondition,
      fetchImpl,
    }).then((result) => ({ result, sent }))
  }

  test('reports a satisfied precondition with the new ETag', async () => {
    const { result } = await put(new Response(null, { status: 200, headers: { etag: '"new"' } }))
    expect(result).toEqual({ status: 'ok', etag: '"new"' })
  })

  test('412 is a clean refusal, not an error', async () => {
    // The stored object was not the one we required. This is how the guard
    // learns it lost a race — it must be a value, never an exception.
    const { result } = await put(new Response('precondition failed', { status: 412 }), {
      ifMatch: '"stale"',
    })
    expect(result).toEqual({ status: 'precondition-failed' })
  })

  test('409 is reported separately so the caller can retry', async () => {
    const { result } = await put(new Response('conflict', { status: 409 }), { ifNoneMatch: '*' })
    expect(result).toEqual({ status: 'conflict' })
  })

  test('other failures throw rather than masquerading as a refusal', async () => {
    // A 500 or an auth failure must never be mistaken for "the guard stopped
    // me", which would silently stop backing the project up.
    await expect(put(new Response('boom', { status: 500 }))).rejects.toThrow(/failed \(500\)/)
    await expect(put(new Response('denied', { status: 403 }))).rejects.toThrow(/failed \(403\)/)
  })

  test('sends the precondition and signature on the wire', async () => {
    const { sent } = await put(new Response(null, { status: 200 }), { ifMatch: '"live"' })
    expect(sent!.method).toBe('PUT')
    expect(sent!.headers.get('if-match')).toBe('"live"')
    expect(sent!.headers.get('authorization')).toContain('AWS4-HMAC-SHA256 Credential=')
    expect(sent!.url).toBe(`${TARGET.endpoint}/${TARGET.bucket}/p/data.tar.gz`)
  })
})
